import{_ as h,C as d,o as r,c as m,a9 as i,b as c,w as s,a,E as o,a8 as u,j as t}from"./chunks/framework.BOiBTRPC.js";const q=JSON.parse('{"title":"Rapid Fire","description":"Thirty rapid-fire DE interview questions across fundamentals, SQL, Spark, streaming, cloud, modeling, and DataOps — answer aloud, then reveal the one-paragraph model answer. Last-72-hours drill.","frontmatter":{"title":"Rapid Fire","description":"Thirty rapid-fire DE interview questions across fundamentals, SQL, Spark, streaming, cloud, modeling, and DataOps — answer aloud, then reveal the one-paragraph model answer. Last-72-hours drill."},"headers":[],"relativePath":"interview/rapid-fire.md","filePath":"interview/rapid-fire.md"}'),p={name:"interview/rapid-fire.md"};function g(y,e,f,w,b,k){const n=d("Mermaid"),l=d("QuizCard");return r(),m("div",null,[e[2]||(e[2]=i('<h1 id="rapid-fire" tabindex="-1">Rapid Fire <a class="header-anchor" href="#rapid-fire" aria-label="Permalink to &quot;Rapid Fire&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — The last 72 hours before a loop aren&#39;t for learning new material; they&#39;re for fluency. These are the questions interviewers ask when they want to know if you <em>live</em> in this vocabulary — each one should take you under a minute aloud.</p></blockquote><h2 id="how-to-use-this-chapter" tabindex="-1">How to use this chapter <a class="header-anchor" href="#how-to-use-this-chapter" aria-label="Permalink to &quot;How to use this chapter&quot;">​</a></h2><p>Read each question, answer it <strong>out loud</strong> in 30-60 seconds, then expand the model answer and compare. You&#39;re not grading correctness — you&#39;re grading whether a crisp, structured answer came out of your mouth without stalling. A right answer delivered in a rambling 4 minutes loses to a tight 45 seconds.</p>',4)),(r(),c(u,null,{default:s(()=>[o(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%2230%20questions%2C%3Cbr%2F%3E7%20groups%22%5D%20--%3E%20F%5B%22Fundamentals%20Q1-5%22%5D%0A%20%20%20%20Q%20--%3E%20S%5B%22SQL%20Q6-10%22%5D%0A%20%20%20%20Q%20--%3E%20K%5B%22Spark%20Q11-15%22%5D%0A%20%20%20%20Q%20--%3E%20T%5B%22Streaming%20Q16-19%22%5D%0A%20%20%20%20Q%20--%3E%20C%5B%22Cloud%20%2F%20storage%20Q20-23%22%5D%0A%20%20%20%20Q%20--%3E%20M%5B%22Modeling%20Q24-27%22%5D%0A%20%20%20%20Q%20--%3E%20D%5B%22DataOps%20Q28-30%22%5D%0A%20%20%20%20F%20%26%20S%20%26%20K%20%26%20T%20%26%20C%20%26%20M%20%26%20D%20--%3E%20R%5B%22say%20it%20aloud%2C%3Cbr%2F%3Ethen%20reveal%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"💡 The structure that sounds senior"),t("p",null,[a("Every model answer here follows the same shape: "),t("strong",null,"definition → why it matters → the trade-off or gotcha"),a(`. Practice that rhythm — it's the difference between "knows it" and "owns it."`)])],-1)),(r(),c(u,null,{default:s(()=>[o(n,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22answer%20in%3Cbr%2F%3E30-60%20seconds%22%5D%20--%3E%20B%5B%22reveal%20model%3Cbr%2F%3Eanswer%22%5D%0A%20%20%20%20B%20--%3E%20C%7B%22tight%20and%20structured%3F%22%7D%0A%20%20%20%20C%20--%3E%7C%22yes%22%7C%20D%5B%22move%20on%22%5D%0A%20%20%20%20C%20--%3E%7C%22rambled%22%7C%20E%5B%22mark%20it%2C%3Cbr%2F%3Eretry%20tomorrow%22%5D%0A%20%20%20%20E%20-.-%3E%7C%22spaced%20re-attempt%22%7C%20A%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h2 id="fundamentals" tabindex="-1">Fundamentals <a class="header-anchor" href="#fundamentals" aria-label="Permalink to &quot;Fundamentals&quot;">​</a></h2><p><strong>Q1 — Partitioning vs clustering: what&#39;s the difference and when does each win?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Partitioning divides a table into disjoint physical segments on a column&#39;s values — pruning happens when a filter hits the partition key, and partitions are individually operable (overwrite, drop). Clustering (BigQuery) / ordering (Iceberg, Delta ZORDER) sorts data <em>within</em> files/partitions by columns — pruning happens via file-level min/max statistics. Partition on low-cardinality columns you filter on almost always (date); cluster on higher-cardinality or multi-column filters (customer_id). Over-partitioning on high-cardinality keys creates tiny-file hell; clustering has no such cliff.</p></details><p><strong>Q2 — What does idempotent mean for a pipeline, and how do you build it?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Re-running produces the same observable result — no duplicates, no double effects. Batch version: partition overwrite, where the output path is the idempotency key. Row version: upsert/<code>MERGE</code> on a natural or idempotency key. The test: &quot;can I rerun this job for yesterday twice and get identical state?&quot; If not, every retry and backfill is a corruption vector.</p></details><p><strong>Q3 — OLTP vs OLAP: the actual engineering differences?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>OLTP optimizes for point reads/writes, row-at-a-time, normalized to kill update anomalies — row stores, indexes, small transactions. OLAP optimizes for scans and aggregates — columnar storage, compression, vectorized execution, denormalized models. The giveaway question: &quot;would you run the dashboard query on the OLTP replica?&quot; — no, because analytical scans starve transactional workloads and the storage layout is wrong for scans anyway.</p></details><p><strong>Q4 — Explain a slowly changing dimension Type 2 in one breath.</strong></p><details class="details custom-block"><summary>Model answer</summary><p>History-preserving dimension: when an attribute changes, close the current row (set end_ts / valid_to) and insert a new row with a new surrogate key — facts join to the version that was valid at event time. The gotchas: key changes must propagate through fact loads, late-arriving dimension updates need restatement logic, and SCD2 explodes size on high-churn attributes — churn-tracking columns belong in SCD1 or a separate table.</p></details><p><strong>Q5 — When do you choose batch over streaming?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Whenever the freshness SLO allows it — streaming costs 3-10× in complexity: state management, late data, watermarks, exactly-once-ish plumbing, harder backfills. The senior answer is demand-driven: &quot;what decision breaks if data is 15 minutes stale?&quot; Fraud scoring → stream. Daily revenue dashboard → batch, and say so confidently. Streaming-everything is a red flag of unowned trade-offs.</p></details><h2 id="sql" tabindex="-1">SQL <a class="header-anchor" href="#sql" aria-label="Permalink to &quot;SQL&quot;">​</a></h2><p><strong>Q6 — <code>RANK</code>, <code>DENSE_RANK</code>, <code>ROW_NUMBER</code> — when does the choice matter?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>At ties. <code>ROW_NUMBER</code> is arbitrary-per-tie unless you add a tiebreak; <code>RANK</code> shares the rank and skips (1,2,2,4); <code>DENSE_RANK</code> shares without skipping (1,2,2,3). Top-N-per-group: <code>ROW_NUMBER</code> guarantees exactly N rows, <code>RANK</code> keeps all tied winners. In dedup, you almost always want <code>ROW_NUMBER</code> with a deterministic <code>ORDER BY</code> — nondeterministic dedup picks a different survivor each run.</p></details><p><strong>Q7 — Why does <code>NOT IN</code> with a subquery sometimes return zero rows?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Three-valued logic: if the subquery produces any NULL, every comparison becomes <code>x != NULL</code> → UNKNOWN → filtered out → empty result. It&#39;s the most common silent-wrong-result in SQL. Fix: <code>NOT EXISTS</code> (null-safe) or filter NULLs in the subquery explicitly. This question is secretly testing whether you debug by reason or by superstition.</p></details><p><strong>Q8 — What causes a join to fan out, and how do you detect it?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Many-to-many or one-to-many where you expected one-to-one — the row count multiplies silently and aggregates inflate. Detection: compare <code>COUNT(*)</code> before and after the join, or check join-key cardinality per side (<code>GROUP BY key HAVING COUNT &gt; 1</code>). Fix upstream: dedupe to one row per key before joining, or aggregate the many-side first. The interviewable skill: name the grain on both sides <em>before</em> writing the join.</p></details><p><strong>Q9 — <code>QUALIFY</code> — what does it do and why do senior DEs love it?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Filters on window-function results directly — <code>QUALIFY ROW_NUMBER() OVER (...) = 1</code> replaces the subquery-wrapper pattern. It exists because <code>WHERE</code> can&#39;t see window results (logical order: WHERE runs before SELECT). BigQuery, Snowflake, DuckDB support it; Postgres and MySQL don&#39;t — in ANSI-pure shops you write the CTE wrapper. Same semantics either way; it&#39;s ergonomics, not power.</p></details><p><strong>Q10 — How do you dedupe while keeping the latest record per key?</strong></p><details class="details custom-block"><summary>Model answer</summary><p><code>ROW_NUMBER() OVER (PARTITION BY key ORDER BY updated_at DESC, tiebreaker) = 1</code>. The two decisions are semantic: the dedup key (natural key, not the row id) and the tiebreak (deterministic — a second column, not just timestamp, or reruns pick different survivors). In the lakehouse world the alternative is <code>MERGE</code>/upsert per micro-batch so you never scan history to dedupe.</p></details><h2 id="spark" tabindex="-1">Spark <a class="header-anchor" href="#spark" aria-label="Permalink to &quot;Spark&quot;">​</a></h2><p><strong>Q11 — What is a shuffle and why is it expensive?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Redistribution of data across executors — required by <code>groupBy</code>, <code>join</code>, <code>distinct</code>, <code>repartition</code>. Expensive because it&#39;s all three costs at once: network transfer + serialization + disk spill for state too big for memory. It&#39;s the usual suspect behind jobs that read 10 GB but run for an hour. Levers: filter before the shuffle, broadcast the small side, pre-partition hot joins, kill skew (salting or AQE skew-split).</p></details><p><strong>Q12 — Broadcast join: when does Spark pick it and when should you force it?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>When one side is under <code>spark.sql.autoBroadcastJoinThreshold</code> (default 10 MB — raise it deliberately, e.g., 100 MB) Spark broadcasts the small side to every executor: no shuffle, a map-side join. Force it with <code>broadcast(small_df)</code> when the optimizer&#39;s stats are stale and it misses. The danger: broadcasting a &quot;small&quot; table that isn&#39;t — OOMed executors are how that lie gets discovered.</p></details><p><strong>Q13 — What is data skew and name two mitigations?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>A few keys holding a disproportionate share of rows — one task processes 100× its share while the cluster idles; shows up as one straggler task in the UI. Mitigations: (1) salting — append a random key suffix to hot keys, aggregate two-stage; (2) broadcast join to eliminate the skewed shuffle; (3) AQE skew-partition splitting (Spark 3+) which auto-splits oversized partitions. Root-cause note: sometimes skew means a bad join key — NULLs or a sentinel value like <code>-1</code> collapsing into one partition.</p></details><p><strong>Q14 — Spark vs Flink for streaming: how do you choose?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Flink for true event-at-a-time streaming: event-time semantics, watermarks, long-lived keyed state, sub-second latency, mature savepoints. Spark Structured Streaming is micro-batch by default — a limited Continuous Processing mode exists (~1ms latency, experimental, rarely used in practice): simpler mental model, shares batch code, better for near-real-time (seconds-to-minutes) pipelines on existing Spark estate. Decision: latency requirement + stateful-window complexity + what the team already runs. &quot;Flink for streaming-native, Spark for streaming-adjacent&quot; is the fair summary.</p></details><p><strong>Q15 — What does <code>cache()</code>/<code>persist()</code> actually do and when does it hurt?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Materializes the DataFrame&#39;s lineage result in memory (or disk) so later actions don&#39;t recompute the DAG. Wins when you read the same DF multiple times (joins to it twice, iterative ML). Hurts when: the data doesn&#39;t fit (spills or evicts), you cache once-read data (pure overhead), or the lineage is cheap anyway (recompute beats memory). Rule: cache at reuse points after expensive narrowing — not reflexively.</p></details><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h2><p><strong>Q16 — Explain watermarks and allowed lateness without jargon.</strong></p><details class="details custom-block"><summary>Model answer</summary><p>A watermark is the engine&#39;s estimate of &quot;how late is late&quot;: event-time progress tracked by the stream, telling windows when they&#39;re probably complete. Events past watermark + allowed-lateness get dropped or side-output. The trade-off is a dial: short lateness → timely results, dropped stragglers; long lateness → completeness, delayed output and more state. Set it from your actual arrival lateness distribution, not vibes — mobile sources need hours, datacenter sources need minutes.</p></details><p><strong>Q17 — Consumer group rebalancing: what happens and why does it matter?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>When a consumer joins/leaves/dies, partitions get reassigned across the group — during the rebalance, consumption pauses and committed offsets resume processing. It matters because rebalances are invisible downtime: a flapping consumer (GC pauses, slow processing beyond <code>max.poll.interval.ms</code>) triggers rebalance storms that look like throughput collapse. Fixes: static group membership, tuned timeouts, faster poll loops, or cooperative rebalancing.</p></details><p><strong>Q18 — How do you handle a consumer that can&#39;t keep up?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>First, is it transient (deploy, spike) or structural? Transient → Kafka retention absorbs it; let lag drain. Structural → scale out (more partitions + consumers — parallelism is bounded by partition count), then reduce per-message cost (batch writes, async I/O, cheaper serialization), then check the sink — usually the consumer isn&#39;t slow, the <em>downstream</em> is. Alert on lag, not throughput: lag is the leading indicator, retention is the countdown clock to data loss.</p></details><p><strong>Q19 — Event time vs processing time — which do you window on and why?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Event time, almost always: it&#39;s when the thing happened, so results are reproducible under replays, restarts, and late data. Processing time is when the engine saw it — results depend on when you run the job, which breaks under backfills and outages. The cost of event time is the lateness machinery (watermarks, allowed lateness). Processing time is acceptable only for metrics about the pipeline itself — never about the business events.</p></details><h2 id="cloud-storage" tabindex="-1">Cloud &amp; storage <a class="header-anchor" href="#cloud-storage" aria-label="Permalink to &quot;Cloud &amp; storage&quot;">​</a></h2><p><strong>Q20 — Parquet vs Avro vs JSON: when does each win?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Parquet is columnar — wins for analytics: column pruning, compression, predicate pushdown; it&#39;s the lakehouse default. Avro is row-based with a schema — wins for streaming/CDC: compact serialization, schema evolution built in, schema registry pairing. JSON is human-readable and schema-flexible — wins for APIs and debugging, loses on size/parse cost for bulk. Pattern: Avro/JSON on the wire, Parquet at rest.</p></details><p><strong>Q21 — What problem do table formats (Iceberg/Delta/Hudi) solve that plain Parquet doesn&#39;t?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Files + metastore ≠ a table. Table formats add: ACID transactions and optimistic concurrency, snapshot isolation + time travel, schema/partition evolution safely, upserts/deletes, and hidden partitioning. Without them: no safe concurrent writes, no rollback of a bad batch, partition changes require rewrites. The trade-off: compaction/maintenance jobs (small-file merge, snapshot expiry) become your ops burden.</p></details><p><strong>Q22 — Small files problem — what is it and why does everyone warn about it?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Thousands of tiny files in object storage kill query performance — per-file overhead (listing, open, footer read, scheduling) dominates the actual scan; metastores and planners choke on file counts, not bytes. Causes: over-partitioning, low-latency streaming sinks committing frequently, too-parallel writers. Fixes: compaction jobs, sized writers, coarser partitions, sink-side file sizing (Iceberg&#39;s <code>target-file-size-bytes</code>). The smell: a query reading 2 GB that plans for 30 seconds.</p></details><p><strong>Q23 — Partitioning an S3/lake table: how do you pick the key?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Filter columns with low cardinality that <em>most</em> queries constrain on — almost always a date grain. Cardinality math: too few partitions → big scans; too many (partition on user_id) → tiny files + metastore pain. Rules of thumb: hundreds-to-thousands of partitions fine; partition size ideally ≥ ~100-256 MB; never partition on a column only <em>some</em> queries use. Iceberg&#39;s hidden partitioning (day(ts), bucket(col)) fixes the &quot;must match path layout&quot; trap.</p></details><h2 id="modeling" tabindex="-1">Modeling <a class="header-anchor" href="#modeling" aria-label="Permalink to &quot;Modeling&quot;">​</a></h2><p><strong>Q24 — Star schema vs one-big-table: what&#39;s the trade-off?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Star: fact + conformed dimensions — compact, join-efficient for BI, self-documenting grain, but every join costs and SCD history adds complexity. OBT: pre-joined wide table — no joins at query time, perfect for a fixed dashboard, but storage-duplicated, harder to maintain, and a dimension change means rewriting the fact. Answer is consumption-driven: many flexible consumers → star; one hot dashboard/query path → OBT or aggregate. Most shops do both: star underneath, OBT/aggregates on top.</p></details><p><strong>Q25 — What grain question do you ask before modeling anything?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>&quot;What does one row represent?&quot; — order, order-line, user-day, account. The grain is the table&#39;s contract: every column must describe exactly one row of that grain, every join must preserve it. Most production data bugs are grain bugs: a &quot;user&quot; table that&#39;s actually user-device, or metrics aggregated at order grain then joined at order-line grain — instant fanout. Saying the grain aloud before modeling is the fastest senior signal in a modeling discussion.</p></details><p><strong>Q26 — When do you denormalize?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>When the join cost or complexity outbids the storage/maintenance cost: hot query paths, BI tools that can&#39;t join well, dimensions flattened into facts for readability, precomputed aggregates. Cost you&#39;re paying: redundancy (the value lives in N places → N update paths → drift risk) and rebuild-on-change. The framing: normalize for write correctness, denormalize for read performance — at the serving layer, not the source of truth.</p></details><p><strong>Q27 — A dashboard metric is suddenly 40% higher after a &quot;small change.&quot; First three checks?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>(1) Grain/fanout — did a join start duplicating rows (the classic 40% = new many-side)? (2) Filter changes — did a <code>WHERE</code> or dedupe change start including rows it excluded (NULL keys, soft-deletes now counted)? (3) Time/partition — did the window or timezone shift, double-counting a boundary? Notice what&#39;s first: not the data, the <em>diff</em>. Reproduce with row-count comparisons at each CTE — bisect the pipeline like code, don&#39;t eyeball aggregates.</p></details><h2 id="dataops" tabindex="-1">DataOps <a class="header-anchor" href="#dataops" aria-label="Permalink to &quot;DataOps&quot;">​</a></h2><p><strong>Q28 — What should a DAG run look like to be truly backfill-safe?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Idempotent per partition — rerunning <code>dt=2024-01-15</code> produces identical state whether run once or ten times, today or six months later. That means: partition-scoped reads and writes (no reading &quot;today&quot;), no mutable lookups that change over time (or snapshot them), deterministic transforms, overwrite semantics. The anti-pattern that fails this: <code>WHERE date = CURRENT_DATE</code> — a job that can&#39;t backfill because it doesn&#39;t know what day it&#39;s for.</p></details><p><strong>Q29 — Data quality checks: where do they live and what do you check?</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Three checkpoints: ingest (contract/schema validation → reject to DLQ, never propagate), transformation (unit tests on logic — dbt tests, expectations), and serving (freshness/volume/drift monitors on the output). What you check: completeness (row counts vs expected), uniqueness (key dupes), validity (ranges, enums, nullability), freshness (max event_time lag), and distribution drift (sudden mean shifts). A check that pages on noise gets muted; reserve alerts for user-impacting breaches.</p></details><p><strong>Q30 — Walk me through your on-call response to &quot;yesterday&#39;s pipeline wrote half the rows.&quot;</strong></p><details class="details custom-block"><summary>Model answer</summary><p>Symptom-first triage: is it upstream (source sent half — check volume SLIs), transform (a filter or join dropped rows — bisect row counts per stage), or sink (write partially failed)? Then the questions that matter: did it <em>fail loud</em> (job error → retry) or <em>succeed silently</em> (worse — you need completeness checks, not status checks)? And can you safely rerun — i.e., is it idempotent? The meta-point interviewers want: your first move is isolation by layer, your second is verifying replay-safety before re-running, not after.</p></details><h2 id="group-to-round-cheat-sheet" tabindex="-1">Group-to-round cheat sheet <a class="header-anchor" href="#group-to-round-cheat-sheet" aria-label="Permalink to &quot;Group-to-round cheat sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Questions</th><th>Round where it surfaces most</th><th>Weak-spot drill</th></tr></thead><tbody><tr><td>Fundamentals</td><td>Q1-5</td><td>Every round, woven into follow-ups</td><td>Say each answer in one breath</td></tr><tr><td>SQL</td><td>Q6-10</td><td>Technical screen + coding onsite</td><td>Whiteboard the query pattern cold</td></tr><tr><td>Spark</td><td>Q11-15</td><td>Senior loops at Spark shops</td><td>Explain shuffle/skew with numbers</td></tr><tr><td>Streaming</td><td>Q16-19</td><td>Real-time platform roles</td><td>Draw a window/watermark timeline</td></tr><tr><td>Cloud &amp; storage</td><td>Q20-23</td><td>Platform/lakehouse roles</td><td>Know one format&#39;s internals well</td></tr><tr><td>Modeling</td><td>Q24-27</td><td>Modeling rounds, BI-heavy teams</td><td>Grain-first on every example</td></tr><tr><td>DataOps</td><td>Q28-30</td><td>Behavioral + production ownership stories</td><td>Rehearse the incident triage aloud</td></tr></tbody></table><h2 id="the-follow-up-pattern" tabindex="-1">The follow-up pattern <a class="header-anchor" href="#the-follow-up-pattern" aria-label="Permalink to &quot;The follow-up pattern&quot;">​</a></h2><p>Rapid-fire questions are almost never the whole question — they&#39;re the on-ramp to a probe. Each group has a characteristic second move:</p><table tabindex="0"><thead><tr><th>Group</th><th>Typical follow-up probe</th></tr></thead><tbody><tr><td>Fundamentals</td><td>&quot;What breaks if you get it wrong?&quot; — the failure mode, not the definition</td></tr><tr><td>SQL</td><td>&quot;Now the data has duplicates / NULLs / arrives late&quot; — the edge case</td></tr><tr><td>Spark</td><td>&quot;The job runs 6× slower than expected — where do you look first?&quot;</td></tr><tr><td>Streaming</td><td>&quot;How late can data be before it&#39;s useless to you?&quot; — the SLO question</td></tr><tr><td>Cloud &amp; storage</td><td>&quot;What&#39;s this architecture&#39;s monthly cost driver?&quot; — cost intuition</td></tr><tr><td>Modeling</td><td>&quot;A stakeholder disputes your grain choice — how do you resolve it?&quot;</td></tr><tr><td>DataOps</td><td>&quot;It&#39;s 3am and the check fires — walk me through your first 10 minutes&quot;</td></tr></tbody></table><p>If your one-paragraph answer already names the trade-off, the probe usually upgrades: &quot;what if volume is 100×?&quot; — that&#39;s the interviewer fishing for whether the answer scales in <em>your head</em>, not just on paper.</p><h2 id="🧠-quiz-—-set-1" tabindex="-1">🧠 Quiz — set 1 <a class="header-anchor" href="#🧠-quiz-—-set-1" aria-label="Permalink to &quot;🧠 Quiz — set 1&quot;">​</a></h2>',74)),o(l,{questions:[{q:"When does clustering beat partitioning on a lake table?",options:["When the filter column has low cardinality","When the table receives frequent deletes","When the table is smaller than 1 GB","When filters hit high-cardinality or multiple columns and partitioning would create tiny files"],correct:3,explain:"Partitioning on high-cardinality keys produces tiny files and metastore pain. Clustering/ZORDER sorts within files and prunes via min/max stats — no partition-count cliff."},{q:"A NOT IN subquery returns zero rows unexpectedly. Most likely cause?",options:["A NULL in the subquery makes every comparison UNKNOWN","NOT IN requires an index","The subquery is empty","Column type mismatch"],correct:0,explain:"x NOT IN (a, b, NULL) is never TRUE — three-valued logic filters every row out. NOT EXISTS is the null-safe equivalent."},{q:"Spark shows one task processing 100x its share while the cluster idles. This is?",options:["A GC problem","Insufficient executors","Data skew — hot keys collapsing into one partition","A serialization bug"],correct:2,explain:"Classic skew signature. Mitigations: salting, broadcast join, or AQE skew-split — and check whether the join key itself is broken (sentinel values like -1)."},{q:"Why does event-time windowing beat processing-time for business metrics?",options:["It is faster","It uses less state","Results are reproducible under replays, restarts, and late data — processing-time results depend on when you ran the job","It requires no watermarks"],correct:2,explain:"Processing-time results change with run timing — a backfill produces different answers. Event time is deterministic given the same events."},{q:"What do table formats like Iceberg add over plain Parquet files?",options:["Automatic data quality checks","Faster single-row lookups","Better compression","ACID transactions, snapshots, schema/partition evolution, and safe deletes/upserts"],correct:3,explain:"Files plus a metastore are not a table — Iceberg adds the transactional layer: concurrent writes, rollback, time travel, and evolution without rewrites."},{q:"A metric jumped 40% after a code change. First check?",options:["Whether a join started fanning out and multiplying rows","Whether the source data changed","Whether a config flag flipped","Whether the dashboard cache is stale"],correct:0,explain:"A sudden step-change after a diff is almost always a grain bug — a new many-side join inflating aggregates. Bisect row counts per CTE before suspecting data."}]}),e[5]||(e[5]=t("h2",{id:"🧠-quiz-—-set-2",tabindex:"-1"},[a("🧠 Quiz — set 2 "),t("a",{class:"header-anchor",href:"#🧠-quiz-—-set-2","aria-label":'Permalink to "🧠 Quiz — set 2"'},"​")],-1)),o(l,{questions:[{q:"What makes a batch job backfill-safe?",options:["Rerunning a partition produces identical state — partition-scoped reads, no CURRENT_DATE reads, deterministic transforms","It runs daily without failing","It uses MERGE instead of INSERT","It writes to a temp table first"],correct:0,explain:"Backfill-safety = idempotency plus time-independence. WHERE date = CURRENT_DATE is the canonical failure — the job cannot know what day it is for."},{q:"Why do small files hurt lake queries so much?",options:["They cannot be partitioned","They compress poorly","Per-file overhead — listing, open, footer read, task scheduling — dominates the actual scan","Object stores charge per file"],correct:2,explain:"Fixed cost per file × thousands of files dwarfs the bytes read. Compaction and sized writers are the fix; over-partitioning and chatty streaming sinks are the causes."},{q:"When does Spark Structured Streaming lose to Flink?",options:["When running on a single node","When the team knows Spark","When you need true event-at-a-time processing, sub-second latency, and complex long-lived keyed state","When data volume is small"],correct:2,explain:"Flink is streaming-native — real event-time, watermarks, savepointed state. Spark is micro-batch — fine for seconds-to-minutes freshness on a Spark estate, wrong for sub-second stateful work."},{q:"What is the trade-off in watermark/allowed-lateness tuning?",options:["Memory vs CPU","Timeliness vs completeness — short lateness drops stragglers; long lateness delays results and grows state","Throughput vs durability","Simplicity vs performance"],correct:1,explain:"The watermark is a dial between early-but-incomplete and late-but-complete. Set it from the measured arrival-lateness distribution — mobile sources need hours."},{q:"Star schema vs one-big-table: what decides?",options:["Consumption pattern — many flexible consumers favor star; one hot query path justifies OBT on top","Whether you use dbt","Table size limits","The BI tool vendor"],correct:0,explain:"Star optimizes join flexibility and conformed semantics; OBT optimizes a fixed read path. Common pattern: star as the modeled layer, OBT/aggregates as serving."},{q:"Your consumer cannot keep up and lag grows. First diagnostic?",options:["Add more consumers immediately","Transient or structural — retention absorbs transients; structural needs parallelism bounded by partitions or cheaper processing","Restart the consumer group","Increase the fetch size"],correct:1,explain:"Scaling first is a guess. Transient lag drains within retention; structural lag needs partition-count parallelism or cheaper per-message work — and usually the sink is slow, not the consumer."}]}),e[6]||(e[6]=i('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://kafka.apache.org/documentation/#design" target="_blank" rel="noreferrer">Kafka documentation — design &amp; semantics</a> — consumer groups, rebalancing, and delivery semantics from the source.</li><li><a href="https://spark.apache.org/docs/latest/tuning.html" target="_blank" rel="noreferrer">Spark tuning guide</a> — skew, broadcast joins, and memory tuning from official docs.</li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/" target="_blank" rel="noreferrer">Flink event-time &amp; watermarks</a> — the authoritative reference for watermark mechanics.</li><li><a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">Apache Iceberg docs</a> — hidden partitioning, snapshots, and maintenance operations.</li><li><a href="https://docs.getdbt.com/docs/build/tests" target="_blank" rel="noreferrer">dbt — tests documentation</a> — the quality-check layer as most shops implement it.</li><li><a href="https://cloud.google.com/bigquery/docs/clustered-tables" target="_blank" rel="noreferrer">BigQuery — clustered vs partitioned tables</a> — the partitioning/clustering trade-off in concrete terms.</li></ul>',2))])}const T=h(p,[["render",g]]);export{q as __pageData,T as default};
